-- ==========================================================
-- BerlinBase: All 22 Districts Complete fact_listings Dataset
-- ==========================================================

DROP TABLE IF EXISTS fact_listings CASCADE;

CREATE TABLE fact_listings (
    listing_id SERIAL PRIMARY KEY,
    district_name VARCHAR(60) NOT NULL,
    borough VARCHAR(60) NOT NULL,
    inside_ringbahn BOOLEAN NOT NULL,
    property_type VARCHAR(20) CHECK (property_type IN ('Room', 'Apartment')),
    lease_type VARCHAR(20) DEFAULT 'unbefristet',
    rental_duration_days INT DEFAULT 365,
    is_swap_only BOOLEAN DEFAULT false,
    wbs_required BOOLEAN DEFAULT false,
    student_dorm_only BOOLEAN DEFAULT false,
    anmeldung_possible BOOLEAN DEFAULT true,
    is_furnished BOOLEAN DEFAULT false,
    size_sqm NUMERIC(5,2) NOT NULL,
    cold_rent_eur NUMERIC(8,2) NOT NULL,
    warm_rent_eur NUMERIC(8,2) NOT NULL
);

